+const TILE_CACHE_NAME = "acoustic-map-tiles-v1";
+const TILE_HOSTS = ["server.arcgisonline.com", "tile.openstreetmap.org"];
+
+function isTileRequest(request) {
+  if (request.method !== "GET") {
+    return false;
+  }
+  try {
+    const url = new URL(request.url);
+    return TILE_HOSTS.includes(url.hostname);
+  } catch (_error) {
+    return false;
+  }
+}
+
+function parseEsri(url) {
+  const match = url.pathname.match(/\/tile\/(\d+)\/(\d+)\/(\d+)$/);
+  if (!match) {
+    return null;
+  }
+  return { z: Number(match[1]), y: Number(match[2]), x: Number(match[3]), type: "esri" };
+}
+
+function parseOsm(url) {
+  const match = url.pathname.match(/\/(\d+)\/(\d+)\/(\d+)\.png$/);
+  if (!match) {
+    return null;
+  }
+  return { z: Number(match[1]), x: Number(match[2]), y: Number(match[3]), type: "osm" };
+}
+
+function parseTile(url) {
+  return parseEsri(url) || parseOsm(url);
+}
+
+function buildTileUrl(baseUrl, parsed, z, x, y) {
+  const url = new URL(baseUrl);
+  if (parsed.type === "esri") {
+    url.pathname = url.pathname.replace(/\/tile\/\d+\/\d+\/\d+$/, `/tile/${z}/${y}/${x}`);
+    return url.toString();
+  }
+  url.pathname = url.pathname.replace(/\/\d+\/\d+\/\d+\.png$/, `/${z}/${x}/${y}.png`);
+  return url.toString();
+}
+
+async function findCachedFallback(request, cache, minZoom = 3) {
+  const url = new URL(request.url);
+  const parsed = parseTile(url);
+  if (!parsed) {
+    return null;
+  }
+
+  for (let targetZoom = parsed.z - 1; targetZoom >= minZoom; targetZoom -= 1) {
+    const scale = 2 ** (parsed.z - targetZoom);
+    const fallbackX = Math.floor(parsed.x / scale);
+    const fallbackY = Math.floor(parsed.y / scale);
+    const fallbackUrl = buildTileUrl(url, parsed, targetZoom, fallbackX, fallbackY);
+    const fallback = await cache.match(fallbackUrl, { ignoreVary: true });
+    if (fallback) {
+      return fallback;
+    }
+  }
+
+  return null;
